namespace Remotely.Tests;

/// <summary>docs/albanian-review.md is generated by tools/loc/albanian-review.py; this keeps it from falling behind the resource files.</summary>
public class LocalizationDocsTests
{
    [Fact]
    public void The_Albanian_review_sheet_lists_every_string_with_its_English_original()
    {
        var sheet = File.ReadAllText(Path.Combine(LocRepo.Root, "docs", "albanian-review.md"));
        var sections = sheet.Split("\n## ").Skip(1).Take(2).Select(x => x.Split('\n')).ToArray();   // one section per app, in the order of LocRepo.Apps
        var missing = new List<string>();
        for (var a = 0; a < LocRepo.Apps.Length; a++)
        {
            var app = LocRepo.Apps[a];
            var rows = sections[a];
            var en = LocRepo.Table(app, LocRepo.English);
            foreach (var (key, albanian) in LocRepo.Table(app, LocRepo.Albanian))
            {
                var row = rows.FirstOrDefault(l => l.StartsWith($"| `{key}` | "));
                if (row is null || !row.Contains(albanian.Replace("|", "\\|")) || !row.Contains(en[key].Replace("|", "\\|")))
                    missing.Add($"{app} {key}");
            }
        }
        Assert.True(missing.Count == 0, "Run python3 tools/loc/albanian-review.py. Out of date: " + string.Join(", ", missing.Take(15)));
    }

    [Fact]
    public void The_sheet_states_how_the_origin_of_each_string_was_found()
    {
        var sheet = File.ReadAllText(Path.Combine(LocRepo.Root, "docs", "albanian-review.md"));
        Assert.Contains("git blame", sheet);
        Assert.Contains("no fluent speaker has", sheet);
    }
}
